import * as runtime from "../src/runtime/index.ts"

const names = Object.keys(runtime)
  .filter((n) => n.startsWith("lean_"))
  .toSorted()

const lines = [
  "/-! Names of the functions the runtime `lean-ts/runtime` exports. Generated by `make gen-externs`. -/",
  "",
  "namespace LeanTs",
  "",
  "def runtimeExterns : Array String := #[",
  names.map((n) => `  "${n}"`).join(",\n"),
  "]",
  "",
  "end LeanTs",
]
process.stdout.write(lines.join("\n") + "\n")
